{
  "groups": [
    {
      "group": "BaseJsonValidator.validate - executionCustomizer throws exception",
      "cases": [
        {
          "input": [
            {
              "parameter": "executionContext",
              "value": "mockExecutionContext"
            },
            {
              "parameter": "node",
              "value": "mockJsonNode"
            },
            {
              "parameter": "format",
              "value": "mockOutputFormat (customize does nothing, format returns \"RESULT-IGNORED\")"
            },
            {
              "parameter": "executionCustomizer",
              "value": "mockExecutionCustomizer (customize throws RuntimeException \"customizer-failure\")"
            }
          ],
          "expected": "RuntimeException with message \"customizer-failure\" is propagated; OutputFormat.format is never invoked.",
          "description": "When the supplied ExecutionContextCustomizer throws an exception, the method must propagate that exception without calling format.format."
        }
      ]
    },
    {
      "group": "BaseJsonValidator.validate - validation messages propagation",
      "cases": [
        {
          "input": [
            {
              "parameter": "executionContext",
              "value": "mockExecutionContext"
            },
            {
              "parameter": "node",
              "value": "mockJsonNode (represents JSON that fails validation, producing two ValidationMessage objects: \"msg1\" and \"msg2\")"
            },
            {
              "parameter": "format",
              "value": "mockOutputFormat (customize does nothing, format records received ValidationMessage set and returns \"RESULT-MESSAGES\")"
            },
            {
              "parameter": "executionCustomizer",
              "value": "null"
            }
          ],
          "expected": "Returns \"RESULT-MESSAGES\"; the mock OutputFormat receives a Set containing exactly the two ValidationMessage objects generated by the validator.",
          "description": "Ensures that the Set produced by the internal validate(executionContext, node) call is passed unchanged to OutputFormat.format."
        }
      ]
    },
    {
      "group": "BaseJsonValidator.validate - null format argument",
      "cases": [
        {
          "input": [
            {
              "parameter": "executionContext",
              "value": "mockExecutionContext"
            },
            {
              "parameter": "node",
              "value": "mockJsonNode"
            },
            {
              "parameter": "format",
              "value": "null"
            },
            {
              "parameter": "executionCustomizer",
              "value": "null"
            }
          ],
          "expected": "NullPointerException is thrown (format is dereferenced before any null‑check).",
          "description": "Verifies that passing a null OutputFormat leads to an immediate NPE, matching the method's contract."
        }
      ]
    },
    {
      "group": "BaseJsonValidator.validate - null executionContext",
      "cases": [
        {
          "input": [
            {
              "parameter": "executionContext",
              "value": "null"
            },
            {
              "parameter": "node",
              "value": "mockJsonNode"
            },
            {
              "parameter": "format",
              "value": "mockOutputFormat (customize records received executionContext null, format returns \"RESULT-NULL-CTX\")"
            },
            {
              "parameter": "executionCustomizer",
              "value": "null"
            }
          ],
          "expected": "Returns \"RESULT-NULL-CTX\"; OutputFormat.customize receives a null executionContext.",
          "description": "Checks that the method tolerates a null ExecutionContext and forwards it to the OutputFormat."
        }
      ]
    },
    {
      "group": "BaseJsonValidator.validate - null node argument",
      "cases": [
        {
          "input": [
            {
              "parameter": "executionContext",
              "value": "mockExecutionContext"
            },
            {
              "parameter": "node",
              "value": "null"
            },
            {
              "parameter": "format",
              "value": "mockOutputFormat (customize does nothing, format returns \"RESULT-NULL-NODE\")"
            },
            {
              "parameter": "executionCustomizer",
              "value": "null"
            }
          ],
          "expected": "Returns \"RESULT-NULL-NODE\"; internal validate(executionContext, null) is invoked (implementation‑dependent) and its result is passed to format.format.",
          "description": "Ensures that a null JsonNode does not cause the method itself to fail; the underlying validator decides how to handle it."
        }
      ]
    },
    {
      "group": "BaseJsonValidator.validate - call order verification",
      "cases": [
        {
          "input": [
            {
              "parameter": "executionContext",
              "value": "mockExecutionContext"
            },
            {
              "parameter": "node",
              "value": "mockJsonNode"
            },
            {
              "parameter": "format",
              "value": "mockOutputFormat (customize records \"customize\", format records \"format\")"
            },
            {
              "parameter": "executionCustomizer",
              "value": "mockExecutionCustomizer (customize records \"customizer\")"
            }
          ],
          "expected": "Returns whatever format.format returns (e.g., \"RESULT-ORDER\"); the recorded call sequence must be [\"customize\", \"customizer\", \"validate\", \"format\"].",
          "description": "Verifies the exact order of operations: OutputFormat.customize → ExecutionContextCustomizer.customize → internal validate → OutputFormat.format."
        }
      ]
    }
  ]
}
